func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()
		prs = append(prs, pr)
		if compress {
			gw := gzip.NewWriter(pw)
			if encryptor != nil {
				ew := encryptor.EncryptWriter(pw)
				pws = append(pws, ew)
				pcs = append(pcs, ew)
				pcs = append(pcs, gw)
			} else {
				pws = append(pws, gw)
				pcs = append(pcs, gw)
			}
		} else {
			if encryptor != nil {
				ew := encryptor.EncryptWriter(pw)
				pws = append(pws, ew)
				pcs = append(pcs, ew)
			} else {
				pws = append(pws, pw)
			}
		}
		pcs = append(pcs, pw)
	}
	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
}
