func LoadKey(cfg Config) ([]byte, error) {
	if !cfg.Enabled {
		return nil, errors.New("encryption is not enabled")
	}
	source := strings.ToLower(strings.TrimSpace(cfg.KeySource))
	var raw []byte
	var err error
	switch source {
	case KeySourceEnv:
		if strings.TrimSpace(cfg.KeyEnvVar) == "" {
			return nil, errors.New("key environment variable is not set for encryption key source env")
		}
		val, ok := os.LookupEnv(cfg.KeyEnvVar)
		if !ok {
			return nil, fmt.Errorf("encryption key environment variable %s is not set", cfg.KeyEnvVar)
		}
		raw, err = base64.StdEncoding.DecodeString(strings.TrimSpace(val))
		if err != nil {
			return nil, fmt.Errorf("failed to decode encryption key from environment variable %s: %w", cfg.KeyEnvVar, err)
		}
	case KeySourceFile:
		if strings.TrimSpace(cfg.KeyFile) == "" {
			return nil, errors.New("key file is not set for encryption key source file")
		}
		data, rerr := os.ReadFile(cfg.KeyFile)
		if rerr != nil {
			return nil, fmt.Errorf("failed to read encryption key file %s: %w", cfg.KeyFile, rerr)
		}
		raw, err = base64.StdEncoding.DecodeString(strings.TrimSpace(string(data)))
		if err != nil {
			return nil, fmt.Errorf("failed to decode encryption key from file %s: %w", cfg.KeyFile, err)
		}
	case KeySourceLiteral:
		if strings.TrimSpace(cfg.Key) == "" {
			return nil, errors.New("key is not set for encryption key source literal")
		}
		raw, err = base64.StdEncoding.DecodeString(strings.TrimSpace(cfg.Key))
		if err != nil {
			return nil, fmt.Errorf("failed to decode encryption key: %w", err)
		}
	case KeySourceDerive:
		if strings.TrimSpace(cfg.Passphrase) == "" {
			return nil, errors.New("passphrase is required for encryption key source derive")
		}
		if strings.TrimSpace(cfg.Salt) == "" {
			return nil, errors.New("salt is required for encryption key source derive")
		}
		salt, derr := base64.StdEncoding.DecodeString(cfg.Salt)
		if derr != nil {
			return nil, fmt.Errorf("failed to decode salt: %w", derr)
		}
		if len(salt) < 16 {
			return nil, fmt.Errorf("salt must be at least 16 bytes, got %d", len(salt))
		}
		raw = deriveKey(cfg.Passphrase, salt)
	default:
		return nil, fmt.Errorf("unsupported encryption key source: %q", cfg.KeySource)
	}
	if len(raw) != keySize {
		return nil, fmt.Errorf("encryption key must be %d bytes, got %d", keySize, len(raw))
	}
	return raw, nil
}
