// EncryptWriter wraps w with an AES-256-GCM encrypting writer.
//
// The stream starts with a 3 byte header (magic 0x4F 0x4D, version 0x01),
// followed by chunks. Each chunk is a 4 byte big-endian length prefix
// (covering nonce + ciphertext + tag), a 12 byte nonce and the ciphertext
// with the appended 16 byte tag. Chunks are terminated by a 4 byte zero
// sentinel, followed by a 32 byte HMAC-SHA256 over all bytes between the
// header and the sentinel, using the encryption key.
func (e *Encryptor) EncryptWriter(w io.Writer) io.WriteCloser {
	ew := &encryptWriter{
		w:    w,
		e:    e,
		aead: e.aead,
		h:    hmac.New(sha256.New, e.key),
		buf:  make([]byte, 0, MaxChunkSize),
	}

	header := []byte{headerMagic0, headerMagic1, formatVersion}
	n, err := w.Write(header)
	ew.h.Write(header[:n])
	if err != nil || n != len(header) {
		ew.err = err
		if ew.err == nil {
			ew.err = errors.New("unexpected partial write")
		}
	}

	return ew
}
