type encryptWriter struct {
	w      io.Writer
	e      *Encryptor
	aead   cipher.AEAD
	h      hash.Hash
	buf    []byte
	closed bool
	err    error
}

// Write implements io.Writer.
func (ew *encryptWriter) Write(p []byte) (int, error) {
	if ew.closed {
		return 0, errors.New("write on closed encrypt writer")
	}
	if ew.err != nil {
		return 0, ew.err
	}

	total := len(p)
	for len(p) > 0 {
		n := copy(ew.buf[len(ew.buf):cap(ew.buf)], p)
		ew.buf = ew.buf[:len(ew.buf)+n]
		p = p[n:]

		if len(ew.buf) == cap(ew.buf) {
			if err := ew.flushChunk(); err != nil {
				ew.err = err
				return 0, err
			}
		}
	}

	return total, nil
}

// flushChunk encrypts the buffered plaintext and writes it as a framed chunk.
func (ew *encryptWriter) flushChunk() error {
	nonce := ew.e.nextNonce()
	ciphertext := ew.aead.Seal(nil, nonce, ew.buf, nil)

	record := make([]byte, 4+ChunkNonceSize+len(ciphertext))
	binary.BigEndian.PutUint32(record, uint32(ChunkNonceSize+len(ciphertext)))
	copy(record[4:], nonce)
	copy(record[4+ChunkNonceSize:], ciphertext)

	n, err := ew.w.Write(record)
	ew.h.Write(record[:n])
	if err != nil {
		return err
	}
	if n != len(record) {
		return errors.New("unexpected partial write")
	}

	ew.buf = ew.buf[:0]
	return nil
}

// Close finalizes the stream. It is idempotent.
func (ew *encryptWriter) Close() error {
	if ew.closed {
		return nil
	}
	ew.closed = true

	if ew.err != nil {
		return ew.err
	}

	var errs error

	if len(ew.buf) > 0 {
		errs = errors.Join(errs, ew.flushChunk())
	}

	sentinel := make([]byte, 4)
	ew.h.Write(sentinel)

	tail := make([]byte, 4+macSize)
	copy(tail, sentinel)
	copy(tail[4:], ew.h.Sum(nil))

	n, err := ew.w.Write(tail)
	if err != nil {
		errs = errors.Join(errs, err)
	} else if n != len(tail) {
		errs = errors.Join(errs, errors.New("unexpected partial write"))
	}

	return errs
}
