import "github.com/liweiyi88/onedump/encryption"

// storageReadWriteCloser pipes readers, writer and closers for fanout the same writer.
// When encryptor is non-nil, the data is encrypted with AES-256-GCM before reaching
// the storage (after gzip compression when compress is true).
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		var outer io.Writer = pw
		if encryptor != nil {
			ew := encryptor.EncryptWriter(pw)
			pcs = append(pcs, ew)
			outer = ew
		}

		if compress {
			gw := gzip.NewWriter(outer)
			pws = append(pws, gw)
			pcs = append(pcs, gw)
		} else {
			pws = append(pws, outer)
		}

		pcs = append(pcs, pw)
	}

	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
}
```

