// EnsureFileSuffix can re-apply them in the canonical order without
// duplicating them. This is what makes EnsureFileSuffix idempotent.
func stripGzEncSuffixes(name string) string {
	for strings.HasSuffix(name, ".gz") || strings.HasSuffix(name, ".enc") {
		if strings.HasSuffix(name, ".gz") {
			name = strings.TrimSuffix(name, ".gz")
		} else {
			name = strings.TrimSuffix(name, ".enc")
		}
	}

	return name
}

// Ensure a file has proper file extension. When shouldGzip is true a ".gz"
// suffix is appended, and when shouldEncrypt is true a ".enc" suffix is
// appended after the ".gz" suffix. The result is idempotent: applying it to
// a filename that already carries the requested suffixes leaves it unchanged.
func EnsureFileSuffix(filename string, shouldGzip, shouldEncrypt bool) string {
	name := stripGzEncSuffixes(filename)

	if shouldGzip {
		name += ".gz"
	}

	if shouldEncrypt {
		name += ".enc"
	}

	return name
}

