func storageReadWriteCloser(count int, compress bool) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		if compress {
			gw := gzip.NewWriter(pw)
			pws = append(pws, gw)
			pcs = append(pcs, gw)
