new_fn = '''// Pipe readers, writer and closers for fanout the same writer.
//
// The writer chain is built from the innermost to the outermost writer: the
// pipe writer, then the gzip writer (when compress is true) and finally the
// encrypting writer (when encryptor is non-nil). Thus the data is compressed
// and then encrypted before it reaches the storages, which reverses by
// reading through DecryptReader and then gzip.NewReader.
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		var inner io.Writer = pw
		var closers []io.Closer

		if compress {
			gw := gzip.NewWriter(inner)
			inner = gw
			closers = append(closers, gw)
		}

		w := inner
		if encryptor != nil {
			ew := encryptor.EncryptWriter(inner)
			w = ew
			// ew is the outermost writer, so it must be closed first to flush
			// the final chunk, the sentinel and the hmac to the inner writers.
			closers = append([]io.Closer{ew}, closers...)
		}

		pws = append(pws, w)
		pcs = append(pcs, closers...)

		// This following append method must be last so that the pipe writer is
		// closed after the gzip and encryption writers have flushed their data.
		// Thus, we put this line here and do not move it to other place.
		pcs = append(pcs, pw)
	}

	return prs, io.MultiWriter(pws...), config.NewMultiCloser(pcs)
